// يرجّع القوائم للواجهة
function getPickLists() {
  return {
    success: true,
    supervisors: PICK_LISTS.SUPERVISORS,
    managers: PICK_LISTS.SUPERVISOR_MANAGER,
    delegateNames: PICK_LISTS.DELEGATE_NAMES,
    pages: PICK_LISTS.PAGES.map(function(p){ return { name: p[0], supervisor: p[1] }; }),
    aliases: PICK_LISTS.ALIASES
  };
}

// تصحيح اسم الصفحة واسم المشرف لمستخدم موجود (يكتب بس العمودين AC و AD لنفس الصف)
// يتأكد إن الإيميل بالصف نفسه قبل الكتابة، وإن القيم من القوائم المعتمدة.
function updateUserPageInfo(rowIndex, email, pageName, supervisor) {
  try {
    var who = Session.getActiveUser().getEmail();
    if (!isProgramAuthorized(who)) return { success: false, error: 'ليس لديك صلاحية' };

    rowIndex = Number(rowIndex);
    var R = CONFIG.MAIN_SHEET.USERS_RANGE;
    if (!(rowIndex >= R.START_ROW && rowIndex <= R.END_ROW)) return { success: false, error: 'رقم صف غير صحيح' };

    var pages = PICK_LISTS.PAGES.map(function(p){ return p[0]; });
    if (pages.indexOf(pageName) < 0) return { success: false, error: 'اسم الصفحة مو من القائمة المعتمدة' };
    if (PICK_LISTS.SUPERVISORS.indexOf(supervisor) < 0) return { success: false, error: 'اسم المشرف مو من القائمة المعتمدة' };

    var lock = LockService.getScriptLock();
    lock.waitLock(15000);
    try {
      var sh = SpreadsheetApp.openById(CONFIG.MAIN_SHEET.ID).getSheetByName(CONFIG.MAIN_SHEET.NAME);
      var C = CONFIG.MAIN_SHEET.COLUMNS;
      var cur = sh.getRange(rowIndex, C.EMAIL, 1, 5).getDisplayValues()[0];
      if (normalizeEmail_(cur[0]) !== normalizeEmail_(email)) {
        return { success: false, error: 'الصف تغيّر — حدّث القائمة وحاول مرة ثانية' };
      }
      var before = { pageName: cur[3], supervisor: cur[4] };
      sh.getRange(rowIndex, C.PAGE_NAME, 1, 2).setValues([[pageName, supervisor]]);
      Logger.log('تصحيح صف ' + rowIndex + ' (' + email + ') بواسطة ' + who + ': ' +
                 JSON.stringify(before) + ' → ' + JSON.stringify({ pageName: pageName, supervisor: supervisor }));
      return { success: true, before: before };
    } finally {
      lock.releaseLock();
    }
  } catch (e) {
    Logger.log('Error in updateUserPageInfo: ' + e.message);
    return { success: false, error: e.message };
  }
}

