function saveFix() {
  if (!fixTarget) return;
  const pageName = document.getElementById('fix-page').value;
  const supervisor = document.getElementById('fix-sup').value;
  if (!pageName || !supervisor) { alert('اختاري الصفحة والمشرفة'); return; }
  const t = fixTarget;

  if (t.mode === 'add') {
    t.user.pageName = pageName;
    t.user.supervisor = supervisor;
    t.user._fixed = true;
    closeFixModal();
    addUser(t.user.rowIndex);
    return;
  }

  const btn = document.getElementById('fix-save-btn');
  btn.disabled = true; btn.textContent = 'جاري الحفظ...';
