      btn.disabled = false; btn.textContent = '✓ حفظ التصحيح';
      if (r && r.success) {
        t.user.pageName = pageName;
        t.user.supervisor = supervisor;
        closeFixModal();
        showAlert('manage', `✓ تم التصحيح: ${t.user.email} → ${pageName} / ${supervisor}`, 'success');
